  --cream-2: #f7efdf;
  --ink: #24382a;
  --ink-soft: #5d705e;
  --green: #3d6b4c;
  --green-deep: #284b35;
  --green-bright: #79a960;
  --leaf: #9bc878;
  --gold: #f3b94f;
  --gold-deep: #d9972e;
  --terracotta: #d17b55;
  --blue: #63a9c4;
  --line: rgba(44, 70, 49, .12);
  --shadow: 0 16px 40px rgba(38, 61, 43, .16);
  --shadow-soft: 0 7px 22px rgba(38, 61, 43, .11);
  --radius: 20px;
  --safe-top: env(safe-area-inset-top, 0px);
  --safe-bottom: env(safe-area-inset-bottom, 0px);
}

* { box-sizing: border-box; }
html, body {
  margin: 0;
  width: 100%;
  height: 100%;
  overflow: hidden;
  background: #d9ead4;
  color: var(--ink);
  font-family: 'Nunito', ui-rounded, 'Trebuchet MS', system-ui, sans-serif;
  -webkit-font-smoothing: antialiased;
  overscroll-behavior: none;
}
button { font: inherit; color: inherit; }
button, [role="button"] { -webkit-tap-highlight-color: transparent; }
button:focus-visible { outline: 3px solid rgba(243, 185, 79, .85); outline-offset: 2px; }
h1, h2, h3, p { margin: 0; }
b, strong { font-weight: 850; }

#scene {
  position: fixed;
  inset: 0;
  width: 100%;
  height: 100%;
  display: block;
  touch-action: none;
  cursor: grab;
  opacity: 0;
  transition: opacity .8s ease;
}
#scene.ready { opacity: 1; }
#scene.dragging { cursor: grabbing; }
#scene.pointing { cursor: pointer; }

#ui {
  position: fixed;
  inset: 0;
  pointer-events: none;
  z-index: 10;
}
#ui button, #ui .glass, #ui .seed-picker, #ui .market-panel, #ui .help-panel,
#ui .modal-layer, #ui .help-layer, #ui .settings-menu, #ui .marker-action {
  pointer-events: auto;
}

.glass {
  background: rgba(255, 250, 240, .88);
  border: 1px solid rgba(255, 255, 255, .72);
  box-shadow: var(--shadow-soft);
  backdrop-filter: blur(16px) saturate(1.1);
  -webkit-backdrop-filter: blur(16px) saturate(1.1);
}

.topbar {
  position: absolute;
  top: calc(16px + var(--safe-top));
  left: 18px;
  right: 18px;
