  box-shadow: inset 0 1px 0 rgba(255,255,255,.7), 0 3px 8px rgba(184, 131, 38, .25);
}
.level-badge span { font-size: 7px; font-weight: 900; text-transform: uppercase; letter-spacing: .5px; }
.level-badge b { font-size: 17px; font-weight: 900; }
