.quest-progress-row { display: flex; align-items: center; gap: 8px; }
.quest-bar { flex: 1; height: 7px; background: #e8e1cf; border-radius: 99px; overflow: hidden; }
.quest-bar i { display: block; width: 0; height: 100%; border-radius: inherit; background: linear-gradient(90deg, #efc15f, #e8a83c); transition: width .5s ease; }
.quest-progress-row > span { color: #8a7a5a; font-size: 9px; font-weight: 900; letter-spacing: .3px; }
.quest-claim {
  width: 100%;
  border: 0;
  border-radius: 10px;
  margin-top: 9px;
  padding: 8px;
  background: linear-gradient(145deg, #f4c65e, #e9a93b);
  color: #5c3d13;
  font-size: 11px;
  font-weight: 900;
  cursor: pointer;
  box-shadow: 0 4px 10px rgba(202,145,45,.25);
  animation: claimPulse 2s ease-in-out infinite;
}
@keyframes claimPulse { 50% { box-shadow: 0 4px 18px rgba(202,145,45,.5); } }

.weather-chip {
  position: absolute;
  top: calc(92px + var(--safe-top));
  right: 18px;
  display: flex;
  align-items: center;
  gap: 8px;
  border-radius: 15px;
  padding: 8px 12px;
  pointer-events: auto;
}
.weather-sun {
  width: 30px; height: 30px;
  display: grid; place-items: center;
  border-radius: 10px;
  background: #fff0bd;
  color: #e6a52e;
  font-size: 19px;
  box-shadow: inset 0 0 0 1px rgba(220,164,45,.12);
}
.weather-chip div { display: flex; flex-direction: column; }
.weather-chip b { font-size: 11px; font-weight: 900; color: #4c614e; line-height: 1.1; }
.weather-chip span { font-size: 8px; color: #8a9583; font-weight: 750; letter-spacing: .2px; }

#markers { position: absolute; inset: 0; pointer-events: none; overflow: hidden; }
.marker {
  position: absolute;
  transform: translate(-50%, -100%);
  display: flex;
  align-items: center;
  justify-content: center;
  will-change: transform, opacity;
}
.marker.mature { pointer-events: auto; }
.marker-action {
  border: 0;
  cursor: pointer;
  border-radius: 99px;
  padding: 7px 11px 7px 8px;
  display: flex;
  align-items: center;
  gap: 4px;
  font-size: 10px;
  font-weight: 900;
  letter-spacing: .1px;
  color: #543c12;
  background: linear-gradient(145deg, #ffe9a6, #f4bd4d);
  box-shadow: 0 5px 14px rgba(148, 103, 22, .3), inset 0 1px 0 rgba(255,255,255,.8);
  transform-origin: 50% 100%;
  animation: markerFloat 2.4s ease-in-out infinite;
  white-space: nowrap;
}
.marker-action:hover { filter: brightness(1.05); transform: scale(1.05); }
.marker-action::after {
  content: "";
  position: absolute;
  bottom: -5px;
  left: 50%;
  width: 10px; height: 10px;
  background: #f5c357;
  transform: translateX(-50%) rotate(45deg);
  border-radius: 2px;
  z-index: -1;
}
.marker-spark { font-size: 13px; line-height: 1; }
@keyframes markerFloat { 50% { transform: translateY(-4px); } }
.marker.dry { pointer-events: auto; }
.water-drop {
  width: 33px;
  height: 33px;
  border-radius: 50% 50% 50% 10px;
  transform: rotate(-45deg);
  border: 0;
  background: linear-gradient(145deg, #9edaf1, #4c9dc4);
  box-shadow: 0 5px 14px rgba(43, 116, 151, .35), inset 0 1px 0 rgba(255,255,255,.6);
  display: grid;
  place-items: center;
  cursor: pointer;
  animation: dropPulse 1.8s ease-in-out infinite;
}
.water-drop span { transform: rotate(45deg); font-size: 15px; line-height: 1; filter: brightness(2); }
@keyframes dropPulse { 50% { transform: rotate(-45deg) scale(1.12); } }

#hover-tip {
  position: fixed;
  z-index: 40;
  min-width: 138px;
  max-width: 220px;
  border-radius: 13px;
  padding: 9px 11px;
  color: #fdfbf2;
  background: rgba(31, 50, 37, .92);
  box-shadow: 0 8px 20px rgba(20, 36, 26, .25);
  backdrop-filter: blur(8px);
  transform: translate(-50%, -100%) translateY(-14px);
  opacity: 0;
  transition: opacity .12s ease;
  pointer-events: none;
}
#hover-tip.show { opacity: 1; }
#hover-tip .tip-title { display: flex; align-items: center; gap: 5px; font-size: 12px; font-weight: 900; }
#hover-tip .tip-sub { color: rgba(255,255,255,.67); font-size: 9px; font-weight: 700; margin-top: 3px; }
#hover-tip .tip-progress { height: 4px; border-radius: 99px; background: rgba(255,255,255,.16); margin-top: 7px; overflow: hidden; }
#hover-tip .tip-progress i { display: block; height: 100%; border-radius: inherit; background: #f4c75d; }

#toast-stack {
  position: absolute;
  top: calc(88px + var(--safe-top));
  left: 50%;
  transform: translateX(-50%);
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 7px;
  z-index: 50;
  width: max-content;
  max-width: min(90vw, 390px);
}
.toast {
  display: flex;
  align-items: center;
  gap: 8px;
  border-radius: 13px;
  padding: 9px 14px 9px 10px;
  background: rgba(255, 250, 240, .96);
  border: 1px solid rgba(255,255,255,.85);
  box-shadow: 0 9px 25px rgba(32, 58, 40, .18);
  font-size: 11px;
  font-weight: 800;
  color: #3d5543;
  animation: toastIn .35s cubic-bezier(.2,.9,.3,1.2);
  backdrop-filter: blur(12px);
}
.toast.leaving { animation: toastOut .28s ease forwards; }
.toast .toast-icon {
  width: 25px; height: 25px;
  display: grid; place-items: center;
  border-radius: 8px;
  background: #edf3df;
  font-size: 14px;
}
.toast.error .toast-icon { background: #fbe9df; }
.toast.gold .toast-icon { background: #fff0c4; }
.toast.gold { color: #71511b; border-color: rgba(240,195,91,.6); }
@keyframes toastIn { from { opacity: 0; transform: translateY(-10px) scale(.96); } }
@keyframes toastOut { to { opacity: 0; transform: translateY(-7px) scale(.97); } }

.hint-pill {
  position: absolute;
  bottom: calc(99px + var(--safe-bottom));
  left: 50%;
  transform: translateX(-50%);
  display: flex;
  align-items: center;
  gap: 7px;
  padding: 7px 13px;
  border-radius: 99px;
  color: #f9f5e7;
  background: rgba(37, 59, 43, .82);
  box-shadow: 0 5px 18px rgba(32, 56, 39, .18);
  font-size: 10px;
  font-weight: 750;
  white-space: nowrap;
  backdrop-filter: blur(8px);
  transition: opacity .3s ease, transform .3s ease;
}
.hint-pill.hide { opacity: 0; transform: translate(-50%, 5px); pointer-events: none; }
.hint-spark { color: #f6ce6b; font-size: 12px; }

.bottom-dock {
  position: absolute;
  bottom: calc(18px + var(--safe-bottom));
  left: 50%;
  transform: translateX(-50%);
  display: flex;
  align-items: stretch;
  gap: 5px;
  padding: 6px;
  border-radius: 21px;
}
.dock-btn {
  position: relative;
  border: 0;
  background: transparent;
  border-radius: 15px;
  min-width: 108px;
  height: 54px;
  padding: 6px 12px 6px 7px;
  display: flex;
  align-items: center;
  gap: 8px;
  cursor: pointer;
  text-align: left;
  transition: background .18s ease, transform .18s ease;
}
.dock-btn:hover { background: rgba(65, 101, 69, .09); transform: translateY(-1px); }
.dock-btn:active { transform: translateY(0) scale(.98); }
.dock-icon {
  width: 39px;
  height: 39px;
  border-radius: 12px;
  display: grid;
  place-items: center;
  flex: 0 0 39px;
  transition: transform .2s ease;
}
.dock-btn:hover .dock-icon { transform: rotate(-4deg) scale(1.04); }
.dock-icon svg { width: 23px; height: 23px; }
.dock-shop .dock-icon { background: #e5f0d7; color: #4f7b4f; }
.dock-water .dock-icon { background: #dceff5; color: #3f86a4; }
.dock-market .dock-icon { background: #fbecc9; color: #a87525; }
.dock-copy { display: flex; flex-direction: column; gap: 1px; }
.dock-copy b { font-size: 12px; line-height: 1.1; font-weight: 900; color: #354d3a; }
.dock-copy small { font-size: 8px; line-height: 1; color: #899582; font-weight: 750; }
.dock-badge {
  position: absolute;
  top: 3px;
  right: 5px;
  min-width: 17px;
  height: 17px;
  padding: 0 4px;
  border-radius: 99px;
  display: none;
  place-items: center;
  background: #e98f54;
  color: white;
  font-size: 8px;
  font-weight: 900;
  box-shadow: 0 2px 5px rgba(140,70,35,.25);
}
.dock-badge.show { display: grid; }

.seed-picker {
  position: absolute;
  left: 50%;
  bottom: calc(88px + var(--safe-bottom));
  transform: translateX(-50%) translateY(10px);
  width: min(820px, calc(100vw - 32px));
  padding: 12px 14px 13px;
  border-radius: 21px;
  background: rgba(255, 250, 240, .96);
  border: 1px solid rgba(255,255,255,.8);
  box-shadow: var(--shadow);
  backdrop-filter: blur(18px);
  z-index: 30;
  opacity: 0;
  transition: opacity .2s ease, transform .25s cubic-bezier(.2,.9,.3,1.1);
}
.seed-picker:not([hidden]) { opacity: 1; transform: translateX(-50%) translateY(0); }
.seed-picker[hidden] { display: block; visibility: hidden; }
.seed-picker-head { display: flex; justify-content: space-between; align-items: center; margin-bottom: 8px; padding: 0 2px; }
.seed-picker-head .eyebrow b { color: #5b7c5c; }
.seed-picker-head h3 { font-size: 15px; line-height: 1.1; color: #2f4b36; font-weight: 900; margin-top: 2px; }
.seed-strip {
  display: flex;
  gap: 7px;
  overflow-x: auto;
  scrollbar-width: none;
  padding: 2px 1px 4px;
}
.seed-strip::-webkit-scrollbar { display: none; }
.seed-choice {
  flex: 0 0 116px;
  border: 1px solid rgba(58, 88, 60, .11);
  background: #fffdf6;
  border-radius: 14px;
  padding: 8px;
  display: flex;
  align-items: center;
  gap: 7px;
  cursor: pointer;
  text-align: left;
  transition: transform .16s ease, box-shadow .16s ease, border-color .16s ease;
}
.seed-choice:hover { transform: translateY(-2px); border-color: rgba(77, 121, 76, .3); box-shadow: 0 5px 12px rgba(45, 75, 49, .1); }
.seed-choice.empty { opacity: .52; filter: grayscale(.55); }
.seed-choice .seed-emoji {
  width: 34px; height: 34px;
  flex: 0 0 34px;
  border-radius: 10px;
  display: grid; place-items: center;
  background: var(--seed-tint, #edf3df);
  font-size: 21px;
}
.seed-choice .seed-info { min-width: 0; flex: 1; }
.seed-choice .seed-info b { display: block; font-size: 10px; line-height: 1.15; color: #3b5540; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.seed-choice .seed-info span { display: block; font-size: 8px; color: #8c9986; font-weight: 750; margin-top: 2px; }
.seed-choice .seed-stock {
  align-self: flex-start;
  background: #eef2e2;
  color: #59734f;
  border-radius: 6px;
  padding: 2px 4px;
  font-size: 8px;
  font-weight: 900;
}
.seed-choice .seed-stock.none { background: #f6e6dc; color: #b36b48; }
.seed-picker-note { font-size: 8px; color: #9b9d8b; font-weight: 750; margin-top: 2px; padding-left: 2px; }

.settings-menu {
  position: absolute;
  top: calc(64px + var(--safe-top));
  right: 18px;
  width: 222px;
  border-radius: 16px;
  padding: 6px;
  z-index: 60;
  transform-origin: top right;
  animation: popIn .18s ease;
}
.settings-menu[hidden] { display: none; }
.settings-menu button {
  width: 100%;
  border: 0;
  background: transparent;
  border-radius: 10px;
  padding: 9px 10px;
  display: flex;
  align-items: center;
  gap: 8px;
  font-size: 10px;
  font-weight: 800;
  color: #4d644f;
  cursor: pointer;
  text-align: left;
}
.settings-menu button:hover { background: rgba(77, 110, 77, .09); }
.settings-menu button.danger { color: #b25f45; }
.settings-menu button span { width: 18px; text-align: center; font-size: 14px; }
.settings-menu p { font-size: 8px; color: #99a091; font-weight: 700; padding: 6px 10px 5px; border-top: 1px solid rgba(60,80,50,.09); margin-top: 4px; }
@keyframes popIn { from { opacity: 0; transform: scale(.95) translateY(-4px); } }

.modal-layer {
  position: absolute;
  inset: 0;
  z-index: 80;
  visibility: hidden;
  opacity: 0;
  transition: opacity .24s ease, visibility .24s;
}
.modal-layer.open { visibility: visible; opacity: 1; }
.modal-backdrop {
  position: absolute;
  inset: 0;
  background: rgba(25, 44, 31, .3);
  backdrop-filter: blur(3px);
  -webkit-backdrop-filter: blur(3px);
}
.market-panel {
  position: absolute;
  top: 16px;
  right: 16px;
  bottom: 16px;
  width: min(530px, calc(100vw - 32px));
  border-radius: 26px;
  background: #fffaf0;
  box-shadow: 0 30px 80px rgba(24, 47, 31, .3);
  border: 1px solid rgba(255,255,255,.9);
  display: flex;
  flex-direction: column;
  overflow: hidden;
  transform: translateX(24px) scale(.99);
  transition: transform .3s cubic-bezier(.2,.8,.3,1);
}
.modal-layer.open .market-panel { transform: translateX(0) scale(1); }
.panel-head {
  padding: 20px 21px 12px;
  display: flex;
  justify-content: space-between;
  align-items: flex-start;
  background: radial-gradient(120% 100% at 10% 0%, #fbf1d7, transparent 70%);
}
.panel-head h2 { font-size: 27px; line-height: 1.05; font-weight: 900; color: #2e4b36; letter-spacing: -.6px; margin-top: 3px; }
.close-btn {
  width: 34px; height: 34px;
  border: 0;
  border-radius: 11px;
  background: #f2ead9;
  color: #66735f;
  font-size: 23px;
  line-height: 1;
  display: grid; place-items: center;
  cursor: pointer;
  transition: background .15s ease, transform .15s ease;
}
.close-btn:hover { background: #eae0ca; transform: rotate(4deg); }
.tabs {
  display: flex;
  gap: 4px;
  padding: 0 18px 11px;
  border-bottom: 1px solid rgba(52, 74, 50, .09);
}
.tab {
  flex: 1;
  border: 0;
  border-radius: 11px;
  padding: 9px 4px;
  background: #f3ecde;
  color: #7a816f;
  font-size: 10px;
  font-weight: 900;
  cursor: pointer;
  transition: background .18s ease, color .18s ease, box-shadow .18s ease;
}
.tab:hover { background: #eee6d4; color: #536b53; }
.tab.active { background: #fffdf7; color: #36563d; box-shadow: 0 2px 8px rgba(46, 68, 43, .11); }
.tab span { color: #b2792c; }
.panel-scroll {
  flex: 1;
  overflow-y: auto;
  padding: 16px 18px 20px;
  scrollbar-width: thin;
  scrollbar-color: #d9cfb7 transparent;
}
.panel-scroll::-webkit-scrollbar { width: 7px; }
.panel-scroll::-webkit-scrollbar-thumb { background: #d9cfb7; border-radius: 99px; }
.panel-foot { padding: 12px 18px calc(14px + env(safe-area-inset-bottom)); border-top: 1px solid rgba(52, 74, 50, .09); background: #fdf7ea; }
.panel-foot:empty { display: none; }

.section-head { display: flex; justify-content: space-between; align-items: end; margin: 1px 0 11px; }
.section-head h3 { font-size: 15px; font-weight: 900; color: #38533d; }
.section-head p { font-size: 9px; font-weight: 700; color: #939b89; }
.market-note {
  display: flex;
  align-items: center;
  gap: 7px;
  border-radius: 11px;
  background: #edf3e2;
  color: #647b5d;
  font-size: 9px;
  font-weight: 750;
  padding: 8px 10px;
  margin-bottom: 13px;
  line-height: 1.3;
}
.market-note b { color: #3d6546; }
.seed-grid { display: grid; grid-template-columns: 1fr 1fr; gap: 8px; }
.seed-card {
  position: relative;
  border-radius: 15px;
  border: 1px solid rgba(56, 80, 54, .1);
  background: #fffdf7;
  padding: 10px;
  display: flex;
  flex-direction: column;
  gap: 7px;
  min-height: 135px;
  transition: transform .18s ease, box-shadow .18s ease;
}
.seed-card:hover { transform: translateY(-2px); box-shadow: 0 7px 18px rgba(44, 70, 46, .09); }
.seed-card.locked { background: #f7f2e7; }
.seed-card-top { display: flex; align-items: flex-start; justify-content: space-between; }
.seed-card-emoji {
  width: 42px; height: 42px;
  border-radius: 12px;
  display: grid; place-items: center;
  background: var(--seed-tint, #edf3df);
  font-size: 25px;
  box-shadow: inset 0 0 0 1px rgba(255,255,255,.5);
}
.seed-level { font-size: 8px; font-weight: 900; color: #9c8a6e; background: #f4ecdb; border-radius: 6px; padding: 3px 5px; }
.seed-level.ok { color: #6a7d58; background: #eef2e1; }
.seed-card h4 { font-size: 12px; font-weight: 900; color: #36503b; line-height: 1.1; }
.seed-meta { display: flex; gap: 7px; color: #8c9585; font-size: 8px; font-weight: 750; flex-wrap: wrap; }
.seed-meta span { display: flex; align-items: center; gap: 2px; }
.seed-card-bottom { margin-top: auto; display: flex; align-items: center; justify-content: space-between; gap: 5px; }
.seed-price { display: flex; align-items: center; gap: 4px; color: #6f5525; font-size: 12px; font-weight: 900; }
.seed-price .mini-coin { width: 14px; height: 14px; border-radius: 50%; background: radial-gradient(circle at 35% 30%, #ffe9a7, #eebd4e); box-shadow: inset 0 0 0 1px rgba(159,108,27,.25); }
.buy-btn, .sell-btn {
  border: 0;
  border-radius: 8px;
  background: #3e6849;
  color: #fffdf5;
  padding: 7px 10px;
  font-size: 9px;
  font-weight: 900;
  cursor: pointer;
  transition: background .15s ease, transform .15s ease;
  white-space: nowrap;
}
.buy-btn:hover, .sell-btn:hover { background: #31573c; transform: translateY(-1px); }
.buy-btn:disabled { background: #d8d2c1; color: #9d9b8c; cursor: not-allowed; transform: none; }
.lock-ribbon {
  position: absolute;
  inset: 0;
  border-radius: inherit;
  background: linear-gradient(145deg, rgba(248,243,231,.45), rgba(248,243,231,.9));
  display: flex;
  align-items: center;
  justify-content: center;
  flex-direction: column;
  gap: 3px;
  color: #7f806e;
  font-size: 9px;
  font-weight: 850;
  pointer-events: none;
}
.lock-ribbon span { font-size: 18px; opacity: .65; }

.inv-list { display: flex; flex-direction: column; gap: 7px; }
.inv-row {
  display: flex;
  align-items: center;
  gap: 9px;
  padding: 9px 10px;
  border-radius: 13px;
  background: #fffdf7;
  border: 1px solid rgba(56, 80, 54, .09);
}
.inv-emoji { width: 36px; height: 36px; flex: 0 0 36px; border-radius: 10px; display: grid; place-items: center; background: var(--seed-tint, #edf3df); font-size: 21px; }
.inv-copy { flex: 1; min-width: 0; }
.inv-copy b { display: block; font-size: 11px; font-weight: 900; color: #36503b; }
.inv-copy span { display: block; font-size: 8px; color: #939a88; font-weight: 700; margin-top: 2px; }
.inv-qty { font-size: 11px; font-weight: 900; color: #5c7358; background: #f0f3e5; border-radius: 7px; padding: 3px 6px; }
.inv-price { min-width: 48px; text-align: right; }
.inv-price b { display: block; color: #7a5a1e; font-size: 12px; font-weight: 900; }
.inv-price span { font-size: 8px; color: #8c9585; font-weight: 750; }
.trend-up { color: #5b8b4d !important; }
.trend-down { color: #c07b52 !important; }
.sell-all-row { display: flex; align-items: center; justify-content: space-between; gap: 10px; }
.sell-total { font-size: 10px; color: #788572; font-weight: 750; }
.sell-total b { display: block; color: #3c5c42; font-size: 19px; font-weight: 900; line-height: 1.1; }
.primary-btn {
  border: 0;
  border-radius: 11px;
  background: linear-gradient(145deg, #4a7754, #365c41);
  color: #fffdf5;
  padding: 11px 18px;
  font-size: 11px;
  font-weight: 900;
  cursor: pointer;
  box-shadow: 0 5px 13px rgba(42, 78, 51, .22);
  transition: transform .15s ease, filter .15s ease;
}
.primary-btn:hover { transform: translateY(-1px); filter: brightness(1.04); }
.primary-btn:disabled { opacity: .45; cursor: not-allowed; transform: none; }
.primary-btn.wide { width: 100%; padding: 13px; }
.ghost-btn {
  border: 1px solid rgba(60, 82, 54, .16);
  background: transparent;
  border-radius: 9px;
  color: #61735e;
  padding: 7px 11px;
  font-size: 9px;
  font-weight: 900;
  cursor: pointer;
}
.empty-state { text-align: center; padding: 35px 10px 40px; }
.empty-state .empty-icon { width: 58px; height: 58px; border-radius: 18px; display: grid; place-items: center; margin: 0 auto 10px; background: #f2ebdc; font-size: 29px; }
.empty-state h3 { font-size: 14px; font-weight: 900; color: #536853; }
.empty-state p { font-size: 9px; color: #939b88; font-weight: 700; margin-top: 4px; line-height: 1.4; }

.upgrade-list { display: flex; flex-direction: column; gap: 8px; }
.upgrade-card {
  display: flex;
  align-items: center;
  gap: 10px;
  padding: 10px;
  border-radius: 14px;
  border: 1px solid rgba(56, 80, 54, .09);
  background: #fffdf7;
