+const raycaster = new THREE.Raycaster();
+const pointerNdc = new THREE.Vector2();
+const pointerState = {
+  down: false,
+  moved: false,
+  startX: 0,
+  startY: 0,
+  lastX: 0,
+  lastY: 0,
+  id: null,
+  downAt: 0,
+  pinchStart: 0,
+  pinchDist: 0,
